mapper.sql:
WHERE i.clan_id = #{criteria.clanId}
  AND i.deleted_at IS NULL




      AND (
        i.branch_id IS NULL
        OR i.branch_id IN

          #{id}

      )


      AND i.branch_id IS NULL





  AND (
    i.privacy_level NOT IN ('private', 'sealed')
    OR i.created_by = #{criteria.actorId}

      OR i.branch_id IN

        #{id}


  )



  AND (
    lower(coalesce(i.title, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(i.summary, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(i.content, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(i.historical_period, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(i.location_text, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
  )



  AND i.category IN

    #{v}




  AND i.branch_id IN

    #{v}




  AND i.data_status IN

    #{v}




  AND i.privacy_level IN

    #{v}




  AND i.is_featured_on_home = #{criteria.featuredOnHome}





      AND EXISTS (
        SELECT 1
        FROM source_binding b
        WHERE b.clan_id = i.clan_id
          AND b.target_type = 'culture_item'
          AND b.target_id = i.id
          AND b.binding_status <> 'archived'
      )


      AND NOT EXISTS (
        SELECT 1
        FROM source_binding b
        WHERE b.clan_id = i.clan_id
          AND b.target_type = 'culture_item'
          AND b.target_id = i.id
          AND b.binding_status <> 'archived'
      )

mapper.select:
SELECT i.*
FROM culture_item i


LIMIT #{limit}
OFFSET #{offset}
